window.MTM=window.MTM||{c:{}};MTM.slides=MTM.slides||{};MTM.slides.u5=[{"n":1,"pg":283,"num":"","title":"Unit V: Gas Turbines – Notation and Sources","sub":"How to read the figures in this set","src":"[Ganesan, Chs. 4, 5; Pounder, Ch. 27]","tx":[{"k":"li","t":"Figures and cycle equations are from V. Ganesan, Gas Turbines. Marine plant (propulsion plants, intake filters, lubrication, maintenance) is from Pounder’s Marine Diesel Engines and Gas Turbines, Ch. 27. • The symbols follow Venkanna (as in Units III and IV). Some Ganesan figures keep their printed labels; the table gives the correspondence. • Slides marked Flagged are short text slides for topics that neither book covers in detail."},{"k":"p","t":"Quantity Ganesan This set"},{"k":"p","t":"Pressure ratio of the cycle (figure axis “r”) r pR Ratio of specific heats k (γ in Ch. 5) γ Absolute velocity, relative velocity c, w V , Vr Maximum-to-minimum temperature ratio t = T3/T1 t = T3/T1 Net work per kg, specific heat WN, Cp WN, cp"}]},{"n":2,"pg":284,"num":"5.1.1","title":"5.1.1 Gas Turbine: Working Cycle","sub":"Simple open-cycle gas turbine","src":"[Ganesan, Sec. 5.1, p. 81 (Fig. 5.1); Ch. 4, p. 63]","tx":[{"k":"fig","t":"Fig. 5.1 Schematic arrangement of a simple gas turbine."},{"k":"li","t":"1–2: compressor raises the pressure of the air (work input)."},{"k":"li","t":"2–3: fuel burns in the combustion chamber at constant pressure (heat addition)."},{"k":"li","t":"3–4: hot gas expands in the turbine (work out- put)."},{"k":"li","t":"4–1: exhaust gas leaves to the atmosphere (heat rejection)."},{"k":"li","t":"The turbine drives the compressor; the net work goes to the load (generator, propeller)."},{"k":"li","t":"Open cycle: fresh air is drawn in continuously. Closed cycle: the same gas circulates (5.1.2)."}]},{"n":3,"pg":285,"num":"5.1.1","title":"5.1.1 Working Cycle: p–V and T–s Diagrams","sub":"Ideal (Joule or Brayton) cycle","src":"[Ganesan, Sec. 5.1, pp. 79–81 (Figs. 5.2, 5.3)]","tx":[{"k":"fig","t":"Figs. 5.2, 5.3 p–V and T–s diagrams of the ideal cycle."},{"k":"li","t":"1–2 and 3–4: isentropic compression and expansion."},{"k":"li","t":"2–3 and 4–1: constant-pressure heat- ing and cooling."},{"k":"p","t":"Ideal-cycle assumptions:"},{"k":"li","t":"The working fluid is a perfect gas with constant cp and γ. • No pressure loss in ducts, chamber or exhaust. • The mass of fuel is neglected."}]},{"n":4,"pg":286,"num":"5.1.1","title":"5.1.1 Working Cycle: Work and Efficiency","sub":"Ideal cycle relations","src":"[Ganesan, Sec. 5.2, pp. 81–83, Eqs. 5.5–5.12]","tx":[{"k":"row","t":["Let t = T3/T1 and T2/T1 = p(γ−1)/γ","R . For unit mass flow:"]},{"k":"p","t":"Work and heat per kg"},{"k":"p","t":"WC = cp(T2 −T1), WT = cp(T3 −T4), WN = WT −WC, Q = cp(T3 −T2)"},{"k":"p","t":"!"},{"k":"row","t":["WN cpT1","1 − 1","\u0010","\u0011"]},{"k":"row","t":["p(γ−1)/γ","— (5.9)"]},{"k":"p","t":"−"},{"k":"p","t":"R −1"},{"k":"row","t":["= t","p(γ−1)/γ"]},{"k":"p","t":"R"},{"k":"p","t":"Thermal efficiency of the simple cycle"},{"k":"p","t":"η = WN"},{"k":"row","t":["Q = 1 − 1","— (5.12)"]},{"k":"p","t":"p(γ−1)/γ"},{"k":"p","t":"R"},{"k":"p","t":"The efficiency depends only on the pressure ratio and the gas (γ); it does not depend on T3."}]},{"n":5,"pg":287,"num":"5.1.1","title":"5.1.1 Specific Work and Efficiency","sub":"Effect of pR and t","src":"[Ganesan, Sec. 5.2, pp. 81–83 (Figs. 5.4, 5.5)]","tx":[{"k":"fig","t":"Figs. 5.4, 5.5 Specific work and efficiency against pressure ratio"},{"k":"li","t":"η rises with pR, but more slowly at high pR; a gas with higher γ gives higher η."},{"k":"li","t":"At constant t the specific work is zero at pR = 1, reaches a maximum, then falls."},{"k":"p","t":"√"},{"k":"li","t":"Maximum work when p(γ−1)/γ R ="},{"k":"p","t":"t, i.e. T2 = T4 (Eq. 5.13)."},{"k":"li","t":"Higher t gives a larger specific work, so a smaller plant; the limit is the blade material and cooling (5.4)."},{"k":"p","t":"(printed axis “r” is pR)."}]},{"n":6,"pg":288,"num":"5.1.1","title":"5.1.1 Temperature, Pressure and Velocity Along the Machine","sub":"Aero-derived gas generator with free power turbine","src":"[Pounder, Ch. 27, p. 865 (Fig. 27.9)]","tx":[{"k":"fig","t":"Fig. 27.9 Main elements and the pressure, temperature and velocity"},{"k":"li","t":"Compressor: pressure and temperature rise steadily; the air velocity is held nearly constant."},{"k":"li","t":"Combustor: temperature climbs to its peak; pressure falls slightly (loss); velocity is kept low for stable burning."},{"k":"li","t":"Compressor turbine: nozzle vanes accel- erate the gas (peak velocity); pressure and temperature fall as work is taken."},{"k":"li","t":"Power turbine: the remaining expansion gives shaft power; the gas leaves at low pressure."},{"k":"p","t":"through the engine (1 kg/cm2 ≈0.98 bar)."}]},{"n":7,"pg":289,"num":"5.1.1","title":"5.1.1 Mass Flow Rate Along the Machine","sub":"How the flow changes from inlet to exhaust","src":"[Ganesan, Sec. 10.2, p. 397; Sec. 14.7, p. 515]","tx":[{"k":"li","t":"Compressor: the mass flow ˙m is constant from stage to stage (continuity), apart from any bleed (anti-surge valves, and the blade-cooling air taken off the HP end)."},{"k":"li","t":"Combustion chamber: fuel is added, so the gas flow is ˙m(1 + f). With an overall air–fuel ratio of 60:1 to 120:1, the fuel adds only about 0.8 to 1.7 %. The bled cooling air does not pass through the chamber."},{"k":"li","t":"Turbine: the blade-cooling air (1 to 3 % of the flow per blade row) re-enters the gas path, so the flow grows along the turbine and is largest at the exhaust."},{"k":"li","t":"Exhaust: the flow equals the air flow plus the fuel flow. A recuperator or intercooler changes temperature, not flow."},{"k":"p","t":"Continuity at any section"},{"k":"p","t":"˙m = ρ A Vf: as the density falls through the turbine, the area A must grow (at roughly constant axial velocity Vf)."},{"k":"flag","t":"Flagged: neither book plots the mass flow along the engine. This slide is compiled from the stated air–fuel ratio and cooling-air fractions."}]},{"n":8,"pg":290,"num":"5.1.1","title":"5.1.1 Heat-Exchange (Regenerative) Cycle","sub":"Using the exhaust heat to warm the compressed air","src":"[Ganesan, Sec. 5.3, pp. 83–85 (Figs. 5.6–5.8)]","tx":[{"k":"fig","t":"Fig. 5.6 Heat-exchange cycle."},{"k":"fig","t":"Figs. 5.7, 5.8 p–V and T–s diagrams. The dashed lines 4–5 and 2–6 show the"},{"k":"p","t":"heat exchange."},{"k":"li","t":"The air leaves the compressor at T2 and is heated in the heat exchanger to T5 (ideally T5 = T4); the exhaust cools from T4 to T6 (ideally T6 = T2). The fuel needed falls."}]},{"n":9,"pg":291,"num":"5.1.1","title":"5.1.1 Heat-Exchange Cycle: Performance","sub":"Ideal heat exchanger","src":"[Ganesan, Sec. 5.3, pp. 84–86 (Figs. 5.9, 5.10), Eq. 5.19]","tx":[{"k":"fig","t":"Figs. 5.9, 5.10 Specific work and efficiency (printed axis “r” is pR)."},{"k":"p","t":"Efficiency of the heat-exchange cycle"},{"k":"p","t":"η = 1 −p(γ−1)/γ"},{"k":"p","t":"R"},{"k":"p","t":"t — (5.19)"},{"k":"li","t":"The specific work is unchanged by the heat exchanger."},{"k":"li","t":"η now rises with t and falls as pR rises. At pR = 1 it equals 1 −1/t."},{"k":"row","t":["• It meets the simple-cycle curve when T2 = T4 (p(γ−1)/γ","√"]},{"k":"p","t":"t); beyond that point a heat exchanger would cool the air."},{"k":"p","t":"R ="},{"k":"li","t":"It pays only at a low pR."}]},{"n":10,"pg":292,"num":"5.1.2","title":"5.1.2 Classification of Gas Turbine Cycles","sub":"Ways of arranging the components","src":"[Ganesan, Ch. 4, pp. 63–73; Pounder, Ch. 27, p. 859 (Fig. 27.7)]","tx":[{"k":"p","t":"Basis Types Remark"},{"k":"p","t":"Working fluid Open / closed Open: fresh air, fuel burnt in it. Closed: same gas recirculated, heater. Shaft arrangement"},{"k":"row","t":["Single: constant load. Twin shaft: variable load (marine, road, rail). Heat exchange Simple / heat exchanger (recuperator)","Single shaft / twin shaft (free power turbine) / twin spool"]},{"k":"p","t":"Exhaust heat warms the compressed air (5.1.1). Compression and expansion"},{"k":"p","t":"Intercooling / reheating Less compressor work, more turbine work; more complex. Compounding Straight / cross Which turbine drives which compressor (twin spool). Waste-heat use Combined cycle (steam), COGES"},{"k":"p","t":"Steam turbine on the exhaust heat (5.7)."}]},{"n":11,"pg":293,"num":"5.1.2","title":"5.1.2 Single-Shaft and Twin-Shaft Arrangements","sub":"Fixed-speed and variable-load plant","src":"[Ganesan, Sec. 4.1, pp. 63–65 (Figs. 4.1, 4.4)]","tx":[{"k":"fig","t":"Fig. 4.1 Single-shaft arrangement: compressor,"},{"k":"p","t":"turbine and load on one shaft. Fig. 4.4 Twin-shaft arrangement: HPC and HPT form the gas generator; the"},{"k":"p","t":"LPT is a separate power turbine."},{"k":"li","t":"Single shaft (Fig. 4.1, p. 64): suited to fixed speed and load, e.g. peak-load power generation. • Twin shaft: the compressor and HP turbine form a gas generator; the power turbine runs at its own speed. Used where flexibility matters: road, rail and marine. • Power is varied by the fuel flow; this lowers pR and the maximum temperature, so part-load efficiency falls. • A heat exchanger can be added but may cut the power by about 10 % (pressure losses)."}]},{"n":12,"pg":294,"num":"5.1.2","title":"5.1.2 Series-Flow and Parallel-Flow Arrangements","sub":"Better part-load control","src":"[Ganesan, Sec. 4.1, p. 66 (Figs. 4.5, 4.6)]","tx":[{"k":"fig","t":"Fig. 4.5 Series flow: the exhaust of the HPT is reheated before"},{"k":"fig","t":"Fig. 4.6 Parallel flow: the separate power turbine has its own"},{"k":"p","t":"combustion chamber."},{"k":"p","t":"the power turbine."},{"k":"li","t":"In both, the power is controlled by adjusting the fuel to the combustion chamber in the power-turbine line."},{"k":"li","t":"The gas generator then keeps its speed and temperature, so the part-load efficiency stays better than in the simple twin-shaft plant."}]},{"n":13,"pg":295,"num":"5.1.2","title":"5.1.2 Intercooling and Reheating","sub":"Complex cycles","src":"[Ganesan, Sec. 4.1, pp. 66–67 (Figs. 4.7, 4.8)]","tx":[{"k":"fig","t":"Fig. 4.7 Series flow with intercooling. Fig. 4.8 Series flow with reheating."},{"k":"li","t":"Intercooling: the compression work per kg is proportional to the inlet temperature, so cooling the air between the LP and HP compressors reduces the work of compression."},{"k":"li","t":"Reheating: burning more fuel between turbine stages raises the turbine work; a heat exchanger limits the extra fuel."},{"k":"li","t":"Intercooling or reheating alone lowers the cycle efficiency (more heat is added); they pay with a heat exchanger. Part-load performance is good, but simplicity and compactness are lost."}]},{"n":14,"pg":296,"num":"5.1.2","title":"5.1.2 Twin-Spool Engine: Straight and Cross Compounding","sub":"Splitting the compressor","src":"[Ganesan, Sec. 4.1, pp. 67–68 (Fig. 4.9)]","tx":[{"k":"fig","t":"Fig. 4.9 Straight-compounded twin-spool arrangement."},{"k":"li","t":"An axial compressor is efficient but unstable off design, especially at start-up, low power or pR > 8 in one compressor."},{"k":"li","t":"Remedy: divide it into LP and HP compressors on separate shafts, each at its own speed."},{"k":"li","t":"Straight compounding: LP compressor driven by the LP turbine, HP compressor by the HP turbine. pR of 10 to 20 is possible; this is the twin-spool en- gine."},{"k":"li","t":"Cross compounding: LP compressor driven by the HP turbine, and the reverse. It claims better part-load efficiency but worsens stability."}]},{"n":15,"pg":297,"num":"5.1.2","title":"5.1.2 Closed-Cycle Arrangements","sub":"Same gas circulated again and again","src":"[Ganesan, Sec. 4.2, pp. 68–70 (Figs. 4.10, 4.11)]","tx":[{"k":"fig","t":"Fig. 4.10 Internal firing with air. Fig. 4.11 External heater, any gas."},{"k":"li","t":"Fuel cannot be burnt in the circulating gas (the oxygen would deplete), so a heater or a make-up air stream is used (Figs. 4.11, 4.10)."},{"k":"li","t":"A gas cooler returns the gas to near-normal compressor inlet temperature, because"},{"k":"row","t":["WC = cpT1","\u0010","\u0011"]},{"k":"p","t":"p(γ−1)/γ"},{"k":"row","t":["R −1","rises with T1."]},{"k":"p","t":"ηC"},{"k":"li","t":"The pressure level can be raised: the same pR gives the same efficiency in a smaller plant."}]},{"n":16,"pg":298,"num":"5.1.2","title":"5.1.2 Closed Cycle: Merits and Working Media","sub":"Advantages, disadvantages and gases","src":"[Ganesan, Secs. 4.2.1–4.4, pp. 70–72 (Table 4.1)]","tx":[{"k":"row","t":["Advantages • High pressure level: smaller plant. • Load varied through the pressure level, so efficiency stays nearly constant. • No blade erosion; no filtering of the gas. • Gases such as helium (γ = 1.66); cheaper fuels.","Gas cp γ k at 0 ◦C R"]},{"k":"p","t":"kJ/kg K W/m K kJ/kg K"},{"k":"p","t":"Air 1.005 1.400 0.0241 0.287 Argon 0.515 1.660 0.0163 0.205 Helium 5.191 1.660 0.1425 2.06 Hydrogen 14.186 1.408 0.1743 4.11"},{"k":"p","t":"R = cp(γ −1)/γ. Table 4.1 of Ganesan misprints R for argon, helium and"},{"k":"row","t":["Disadvantages • Bulky heater; leakage; large cooler. • Stationary plants only.","hydrogen (0.151, 10.050, 59.934); the values above are recomputed. A good medium is cheap, stable, non-toxic, with high cp, high γ and high thermal con- ductivity (smaller heat exchangers): helium and hydrogen."]}]},{"n":17,"pg":299,"num":"5.1.2","title":"5.1.2 Cycle Configurations Used at Sea","sub":"Six configurations studied for a marine gas turbine","src":"[Pounder, Ch. 27, p. 859 (Fig. 27.7)]","tx":[{"k":"fig","t":"Fig. 27.7 Gas turbine cycle configurations (Mitsubishi)."},{"k":"li","t":"A Simple: compressor, combustor, tur- bine. • B Intercooled: less HP compressor power. • C ICR: adds a recuperator on the ex- haust. • D Reheat: second combustor after the HP turbine. • E Intercooled reheat. • F Combined: steam turbine on the ex- haust heat. ICR was favoured: high efficiency and power at pR ≈20. The combined-cycle boiler is too heavy for a ship."}]},{"n":18,"pg":300,"num":"5.1.2","title":"5.1.2 Part-Load Fuel Consumption of Different Cycles","sub":"Specific fuel consumption against load","src":"[Pounder, Ch. 27, p. 857 (Fig. 27.5)]","tx":[{"k":"fig","t":"Fig. 27.5 sfc against load (horizontal axis: load, % of full power): gas turbine cycles and a slow-speed diesel."},{"k":"li","t":"The simple-cycle gas turbine has a high sfc that rises sharply at part load."},{"k":"li","t":"Recuperated and intercooled-recuperated engines have a much flatter curve, close to a diesel."},{"k":"li","t":"Marine gas turbines: about 25 % efficiency in 1960, near 35 % in the 1970s, over 40 % for large simple- cycle units today."},{"k":"li","t":"Gas turbines below about 5 MW are significantly less efficient than diesels."}]},{"n":19,"pg":301,"num":"5.1.2","title":"5.1.2 Intercooled-Recuperated (ICR) Cycle","sub":"Layout compared with the simple cycle","src":"[Pounder, Ch. 27, p. 858 (Fig. 27.6)]","tx":[{"k":"fig","t":"Fig. 27.6 ICR and simple-cycle gas turbines (Rolls-Royce)."},{"k":"li","t":"IPC, HPC: intermediate- and high- pressure compressors; HPT, IPT: their turbines; LP PT: the power turbine."},{"k":"li","t":"The intercooler (sea-water cooled) sits between IPC and HPC."},{"k":"li","t":"The recuperator uses the exhaust gas to heat the air entering the combustor (B)."},{"k":"li","t":"Variable-area nozzles (VAN) on the power turbine hold its entry temper- ature constant as power falls, so the recuperator keeps its effectiveness."},{"k":"li","t":"Result: a flat sfc across the load range."}]},{"n":20,"pg":302,"num":"5.1.2","title":"5.1.2 Intercoolers and Recuperators","sub":"ICR system of the Rolls-Royce WR-21","src":"[Pounder, Ch. 27, pp. 883–884 (Fig. 27.20)]","tx":[{"k":"fig","t":"Fig. 27.20 ICR system of the WR-21 gas turbine."},{"k":"li","t":"Intercooler: cools the air before the HP compressor: less compres- sor work (more net power) and a lower HP delivery temperature, which helps the recuperator."},{"k":"li","t":"Recuperator: exhaust heat warms the compressed air before the combustor, so less fuel is needed."},{"k":"li","t":"Variable-area nozzles (VAN) hold the power-turbine entry temperature at part load, keeping the recuperator ef- fective."},{"k":"li","t":"WR-21: about 205 g/kWh from full power down to about 30 % power."}]},{"n":21,"pg":303,"num":"5.1.2","title":"5.1.2 Intercooler and Recuperator: Package Layout","sub":"WR-21 gas turbine package","src":"[Pounder, Ch. 27, pp. 884–888 (Fig. 27.21)]","tx":[{"k":"fig","t":"Fig. 27.21 Layout of the WR-21 package."},{"k":"li","t":"The intake is a radial intake; five inter- cooler segments are housed in the inter- case between the compressors."},{"k":"li","t":"The recuperator sits in the enclosure above the engine; ducts carry the exhaust through it."},{"k":"li","t":"Bypass valves on the intercooler avoid condensation; a recuperator bypass lowers combustion temperature to cut NOx."},{"k":"li","t":"Service lesson: the intercooler failed in warm sea water (above about 30 °C)."}]},{"n":22,"pg":304,"num":"5.1.3","title":"5.1.3 Structural Arrangement: Marine Gas Turbine","sub":"LM2500 aero-derived gas turbine","src":"[Pounder, Ch. 27, pp. 869, 874 (Fig. 27.14)]","tx":[{"k":"fig","t":"Fig. 27.14 LM2500 cutaway: compressor, annular combustor, HP turbine, LP power turbine."},{"k":"li","t":"Compressor: 16 stages, pressure ratio 18:1; variable stators and guide vanes for easy starting and a good stall margin."},{"k":"li","t":"Combustor: fully annular, externally mounted fuel nozzles."},{"k":"li","t":"HP turbine: two stages, air-cooled; drives the compressor and the accessory gearbox."},{"k":"li","t":"Power turbine: six stages, a low-speed, low-stress machine driven by the gas generator exhaust."}]},{"n":23,"pg":305,"num":"5.1.3","title":"5.1.3 Structural Arrangement: Two-Shaft Engine","sub":"Two-shaft engine: flow diagram","src":"[Pounder, Ch. 27, pp. 866–869 (Fig. 27.12)]","tx":[{"k":"fig","t":"Fig. 27.12 GT35 (SGT-500) marine installation driving a water jet through a"},{"k":"li","t":"A jet engine becomes a gas gener- ator; adding a free power turbine gives the shaft-power gas turbine."},{"k":"li","t":"GT35 gas generator: 10-stage LP and 8-stage HP compressors, seven can-type combustors, 1-stage HP and 2-stage LP turbines."},{"k":"li","t":"The 3-stage power turbine drives the load through a gear."},{"k":"p","t":"gear."},{"k":"li","t":"Rating 17 300 kW, efficiency 33 %."}]},{"n":24,"pg":306,"num":"5.1.3","title":"5.1.3 Basic Description of a Gas Turbine","sub":"Important components","src":"[Ganesan, Ch. 1, p. 3 (Fig. 1.1); Pounder, Ch. 27, p. 864]","tx":[{"k":"fig","t":"Fig. 1.1 A simple gas turbine."},{"k":"li","t":"Compressor: draws in and compresses the air (axial for large flows)."},{"k":"li","t":"Combustion chamber: fuel is injected, mixed with the air and burnt at constant pressure (5.2)."},{"k":"li","t":"Turbine: absorbs enough power to drive the com- pressor; the power turbine takes the rest as shaft power (5.3)."},{"k":"li","t":"Nozzle: the stationary nozzle guide vanes direct and accelerate the gas onto the rotor; the exhaust nozzle or volute leads the gas out."},{"k":"li","t":"Blades: aerofoils of compressor and turbine; the hot turbine blades are the life-limiting part (5.4)."}]},{"n":25,"pg":307,"num":"5.1.3","title":"5.1.3 Exhaust Nozzle","sub":"Function and shape","src":"[Ganesan, Sec. 13.5, pp. 488–491 (Fig. 13.10)]","tx":[{"k":"fig","t":"Fig. 13.10 Convergent exhaust nozzle."},{"k":"li","t":"The nozzle divides the energy of the combustor exit gas between the turbine and the jet: it converts ther- mal energy into kinetic energy."},{"k":"li","t":"It also acts as a back-pressure control: the throat area sets the engine operating line."},{"k":"li","t":"Convergent nozzles for subsonic flow; convergent– divergent nozzles for supersonic flow."},{"k":"li","t":"A larger throat reduces back pressure, moves the compressor away from surge and eases starting."},{"k":"li","t":"In a marine shaft engine the power turbine takes the energy; there is no propelling jet. The exhaust leaves through the exhaust volute around the power turbine (Fig. 27.10, p. 320) and the uptake (5.7)."}]},{"n":26,"pg":308,"num":"5.2.1","title":"5.2.1 Combustion Chamber: Function and Requirements","sub":"What the chamber must do","src":"[Ganesan, Secs. 10.2, 10.5, pp. 397–405]","tx":[{"k":"p","t":"The chamber burns the fuel in the compressor air and delivers a steady stream of gas at a controlled temperature to the turbine."},{"k":"row","t":["Requirements • Complete combustion of the fuel. • Minimum pressure loss. • No carbon deposits; smoke only as a light haze. • Reliable ignition over a wide range of con- ditions. • Controlled temperature and velocity at the turbine inlet. • Small volume and weight; reliable and durable.","Why it is difficult • Air velocity of 30–60 m/s, but flame speed only 2–5 m/s: a low-velocity re- gion is needed. • Overall air–fuel ratio 60:1 to 120:1, against about 15:1 for complete (stoi- chiometric) burning. • Stable burning from full load to idle."]}]},{"n":27,"pg":309,"num":"5.2.2","title":"5.2.2 Apportioning the Airflow","sub":"Zones of the combustion chamber","src":"[Ganesan, Secs. 10.6–10.7, pp. 405–407 (Fig. 10.3); Pounder, p. 866]","tx":[{"k":"fig","t":"Fig. 10.3 Typical combustion chamber: baffle, liner (flame"},{"k":"p","t":"Zone Air Purpose"},{"k":"p","t":"Primary 15–20 % Near-stoichiometric burning; flame held by swirl or baffle. Secondary about 30 % Completes the burning; added through liner holes. Tertiary (dilution)"},{"k":"row","t":["the rest (about 50 %)","Cools the gas to the turbine inlet temperature; even temperature profile."]},{"k":"p","t":"tube) and outer casing."},{"k":"li","t":"Air is added in stages (all at once would chill the flame). Secondary plus tertiary air is about 80 %: the “three-quarters” of 5.2.2."}]},{"n":28,"pg":310,"num":"5.2.2","title":"5.2.2 Primary Zone: Flame Stabilisation (1)","sub":"Swirl vanes and the Lucas chamber","src":"[Ganesan, Sec. 10.7.1, p. 408 (Figs. 10.4, 10.5)]","tx":[{"k":"fig","t":"Fig. 10.4 Flow pattern in the primary zone (swirl vanes). Fig. 10.5 A Lucas chamber with an inlet swirler."},{"k":"li","t":"The flame must be held in an airstream much faster than the flame speed: a recirculation zone returns burning gas to the fresh fuel and air."},{"k":"li","t":"Swirl vanes give a vortex; the low pressure at the centre draws the hot gas upstream. Lucas adds many small air jets for finer mixing."},{"k":"li","t":"Baffles: a few large baffles stabilise better than many small ones."}]},{"n":29,"pg":311,"num":"5.2.2","title":"5.2.2 Primary Zone: Flame Stabilisation (2)","sub":"G.E. chamber, upstream injection, dilution","src":"[Ganesan, Secs. 10.7–10.8, pp. 408–410]","tx":[{"k":"fig","t":"Fig. 10.6 G.E. chamber: eddies from a row of holes. Fig. 10.7 Upstream fuel injection."},{"k":"li","t":"G.E. type: the recirculation is formed by jets from holes just downstream of the injector; their position is critical."},{"k":"li","t":"Upstream injection: better mixing, but the fuel pipe sits in the flame and must be cooled."},{"k":"li","t":"Dilution: about three-quarters of the total air (secondary and tertiary) is added to one-quarter of the reactant gas, through holes or slots. The jets must reach the axis to avoid a hot core; the size and number of holes is a compromise."}]},{"n":30,"pg":312,"num":"5.2.3","title":"5.2.3 Flame Tube Cooling Methods","sub":"Keeping the liner wall below its limit","src":"[Ganesan, Sec. 10.10.1, pp. 411–412 (Fig. 10.9)]","tx":[{"k":"fig","t":"Fig. 10.9 Film cooling of the flame tube: (a) overlapping sections with"},{"k":"p","t":"The liner is heated by convection from the gas and radiation from the flame, and cooled by the air flowing in the annulus."},{"k":"p","t":"a corrugated spacer (middle view), (b) holes with splash ring."},{"k":"li","t":"Film cooling: narrow gaps between overlapping liner sections (corrugated “wiggle strip” spacers) sweep a film of cool air along the inside wall. • Hole and splash ring: a ring of small holes with a splash ring turns the jets along the wall (Fig. 10.9b). • Effusion (porous wall) cooling: needs much less air; considered above about 1500 K turbine inlet temperature. • Higher cycle temperatures leave less air for cooling, and hotter compressor air cools less."}]},{"n":31,"pg":313,"num":"5.2.4","title":"5.2.4 Types of Combustion Chambers","sub":"Single, can, turbo-annular, annular","src":"[Ganesan, Secs. 10.4, 10.9 (Fig. 10.8); Pounder, p. 871 (Fig. 27.13)]","tx":[{"k":"fig","t":"Fig. 10.8 Annular combustion chamber. Fig. 27.13 Seven can-type chambers of the GT35"},{"k":"p","t":"(foreground)."},{"k":"li","t":"Single large chamber: heavy industrial plant; low velocity, high efficiency, long life. • Multiple (can, tubular) chambers: spaced round the shaft, each with its own injector; common on marine and aircraft engines (GT35: seven cans). A can can be removed alone. • Turbo-annular: cans inside a common annular casing. Annular: a continuous annulus between compressor and turbine; least pressure loss and smallest diameter. • Cans suit the divided flow of a centrifugal compressor; the annular form suits an axial compressor (see the table)."}]},{"n":32,"pg":314,"num":"5.2.4","title":"5.2.4 Comparison of Combustion Chamber Types","sub":"Tubular, turbo-annular and annular","src":"[Ganesan, Secs. 10.3.1, 10.4, 10.9, pp. 399–411]","tx":[{"k":"p","t":"Advantages Disadvantages Pressure loss factor"},{"k":"row","t":["Tubular (can) Easy to develop and replace;","Large and heavy; high pressure loss.","about 35"]},{"k":"p","t":"uniform exit temperature from each can."},{"k":"row","t":["Cans inside a common casing.","Intermediate. about 25"]},{"k":"p","t":"Turbo- annular"},{"k":"row","t":["Annular Compact; least pressure loss; continuous sheet of gas.","Hard to get an even fuel and temperature distribution; weaker structure; full-flow test rig needed.","about 18"]},{"k":"p","t":"˙m2/2ρ1A2"},{"k":"row","t":["\u000e \u0000","\u0001"]},{"k":"row","t":["The pressure loss factor = ∆p0","is based on the reference velocity (Eq. 10.2)."]},{"k":"p","t":"m"},{"k":"flag","t":"Flagged: Ganesan gives the three pressure loss factors; the advantages and disadvantages of the turbo-annular type are standard practice."}]},{"n":33,"pg":315,"num":"5.2.5","title":"5.2.5 Fuel Injection","sub":"Swirl (centrifugal) atomizer","src":"[Ganesan, Sec. 10.10.2, pp. 412–415 (Fig. 10.10)]","tx":[{"k":"fig","t":"Fig. 10.10 Swirl-type atomizer."},{"k":"p","t":"The injector must meter the fuel and atomize it into fine droplets for fast evaporation and mixing."},{"k":"li","t":"Fuel enters the swirl chamber tangentially; the spinning sheet leaves the orifice as a hollow cone of droplets. • The flow varies as the square root of the injection pressure, so a wide flow range needs a very large pressure range. • A good atomizer: wide flow range, no moving parts, even distribution and identical units in a multi-injector system. • The duplex burner opens a second port at a set pressure."}]},{"n":34,"pg":316,"num":"5.2.6","title":"5.2.6 Combustion Chamber Performance","sub":"Pressure loss, efficiency and intensity","src":"[Ganesan, Sec. 10.3, pp. 398–402]","tx":[{"k":"fig","t":"Fig. 10.2 Variation of pressure loss factor."},{"k":"p","t":"Combustion efficiency"},{"k":"p","t":"ηb = actual total-head temperature rise theoretical total-head temperature rise"},{"k":"row","t":["\u0012T02","\u0013"]},{"k":"p","t":"−1"},{"k":"row","t":["• Pressure loss factor PLF = K1 + K2","(Eq. 10.2)."]},{"k":"p","t":"T01"},{"k":"p","t":"K1: cold loss (friction, turbulence); K2: hot loss (heat ad- dition). It lowers the work and raises the fuel used."},{"k":"li","t":"Combustion intensity = heat release rate \u000e"},{"k":"p","t":"(volume × pressure); lower is easier. Aircraft chambers are about ten times more intense than industrial ones."},{"k":"li","t":"Residual fuels bring vanadium, alkali salts and ash: hot corrosion and deposits on the nozzle blades (Sec. 10.10.4)."}]},{"n":35,"pg":317,"num":"5.3.1","title":"5.3.1 Gas Turbine Stage","sub":"Nozzle row and rotor row","src":"[Ganesan, Ch. 11, pp. 421–422 (Fig. 11.1)]","tx":[{"k":"fig","t":"Fig. 11.1 A turbine stage: fixed nozzle blade row followed by the rotor blade row."},{"k":"li","t":"In the nozzle (stator) blades the gas expands and gains velocity; it is turned onto the rotor."},{"k":"li","t":"In the rotor blades the momentum change of the gas turns the wheel (work output)."},{"k":"li","t":"A gas turbine has few stages, because the pressure ratio is low compared with a steam turbine."},{"k":"li","t":"Stages are impulse or reaction; several stages on one shaft form a multistage turbine."}]},{"n":36,"pg":318,"num":"5.3.1","title":"5.3.1 Impulse and Reaction Stages","sub":"Pressure and velocity through the stage","src":"[Ganesan, Secs. 11.1–11.2, pp. 422–424 (Figs. 11.2, 11.3)]","tx":[{"k":"fig","t":"Fig. 11.2 Impulse stage."},{"k":"fig","t":"Fig. 11.3 Reaction stage."},{"k":"li","t":"Impulse: the whole pres- sure drop is in the nozzles; the rotor only deflects the flow. • Reaction: expansion in nozzle and rotor; the rela- tive velocity rises in the ro- tor. • Degree of reaction = static pressure change in the ro- tor"},{"k":"p","t":"\u000e"},{"k":"p","t":"change across the stage; 50 % gives symmet- rical blades."}]},{"n":37,"pg":319,"num":"5.3.2","title":"5.3.2 Turbine Arrangements","sub":"Single-shaft, twin and free turbines","src":"[Ganesan, Secs. 4.1, 11.3; Pounder, Ch. 27, pp. 866–869]","tx":[{"k":"p","t":"Arrangement How it works Use"},{"k":"row","t":["Single shaft (for example a three-stage turbine)","All stages on one shaft; they drive the compressor and the load together at the same speed.","Fixed speed and load: generators (p. 293)."]},{"k":"p","t":"pR of 10–20; better stability (p. 296)."},{"k":"row","t":["Twin turbine (twin spool)","HP turbine drives the HP compressor, LP turbine the LP compressor, on coaxial shafts."]},{"k":"row","t":["Free power turbine The gas generator has its own turbine; a separate power turbine on an independent shaft takes the remaining energy.","Marine propulsion and variable load (p. 305)."]},{"k":"li","t":"Marine examples: LM2500 has a 2-stage HP and a 6-stage power turbine; GT35 has 1 + 2 stages in the gas generator and a 3-stage power turbine."}]},{"n":38,"pg":320,"num":"5.3.2","title":"5.3.2 Free Power Turbine","sub":"Power turbine of a Rolls-Royce Spey","src":"[Pounder, Ch. 27, pp. 866–867 (Fig. 27.10)]","tx":[{"k":"fig","t":"Fig. 27.10 Power turbine of a Spey SM1C engine."},{"k":"li","t":"It runs at any speed from stop to full power, set by its power and the load be- hind it."},{"k":"li","t":"The starting power is small: only the gas generator rotors are turned."},{"k":"li","t":"No critical speeds in the running range; ideal for manoeuvring."},{"k":"li","t":"Linked to the gas generator by a bel- lows joint or mounted on the inter- turbine duct."},{"k":"li","t":"Surrounded by an exhaust volute lead- ing to the stack; designed to last the life of the plant."}]},{"n":39,"pg":321,"num":"5.3.3","title":"5.3.3 Nozzle Guide Vanes","sub":"Stationary vanes ahead of the first rotor","src":"[Ganesan, Secs. 11.1, 14.7; Pounder, Ch. 27, p. 866]","tx":[{"k":"li","t":"The nozzle guide vanes (NGVs) are the first row of fixed blades after the combustor: they accelerate the gas and turn it onto the first rotor at the correct angle."},{"k":"li","t":"They see the highest gas temperature of any turbine part, so they are cooled with compressor air (Ganesan: “blades and vanes” are cooled), and made of nickel- or cobalt-base alloys."},{"k":"li","t":"Their total throat area fixes the flow the gas generator can pass; on some engines the power turbine nozzles have variable area (WR-21) to hold the entry temperature at part load."},{"k":"li","t":"They are not subject to the centrifugal load of rotor blades, so thermal stress and hot corrosion are the main limits."},{"k":"flag","t":"Flagged: Ganesan describes the nozzle row only as part of the stage (Fig. 11.1); the detail on NGV cooling and materials is general practice."}]},{"n":40,"pg":322,"num":"5.3.4","title":"5.3.4 Turbine Blades","sub":"Loads and types of blade","src":"[Ganesan, Ch. 14, pp. 501–503, 513–519]","tx":[{"k":"row","t":["Forces on a rotor blade • Centrifugal tensile load (speeds up to 30 000 rpm). • Bending from the gas force. • Thermal stress and creep at high tempera- ture. • Erosion and corrosion by the hot gas.","Types of turbine blade • Impulse or reaction section (symmetri- cal at 50 % reaction). • Solid (uncooled) or hollow (air-cooled) (5.4). • Forged, cast or fabricated (5.4). • Rotor blades with a tip shroud or free tips (small tip clearance). • Long blades are twisted from root to tip, because the blade speed rises along the span."]},{"k":"flag","t":"Flagged: Ganesan does not list blade shapes; the types above (shrouded tips, twisted blades) are standard practice, added for the syllabus."}]},{"n":41,"pg":323,"num":"5.3.5","title":"5.3.5 Fixing Blades to the Disc (1)","sub":"Bulb root, tee and double tee, anchor pin","src":"[Ganesan, Sec. 14.3, pp. 508–510 (Figs. 14.1–14.3)]","tx":[{"k":"fig","t":"Fig. 14.1 Bulb root. Fig. 14.2 Tee and double tee. Fig. 14.3 Anchor pin."},{"k":"li","t":"Bulb root: bulb-shaped root held by steel pins; end movement stopped by swaging the rotor metal. • Tee and double tee: the root slides into a T-slot in the wheel and a wedge locks it. • Anchor pin: a pin through the wheel and root, secured by a nut."}]},{"n":42,"pg":324,"num":"5.3.5","title":"5.3.5 Fixing Blades to the Disc (2)","sub":"Fir tree, grub screw, welding","src":"[Ganesan, Sec. 14.3, pp. 509–511 (Figs. 14.4–14.6)]","tx":[{"k":"fig","t":"Fig. 14.4 Fir-tree root. Fig. 14.5 Grub screw. Fig. 14.6 Welding."},{"k":"li","t":"Fir tree (most gas turbines today): the rotor is not weakened, the contact is distributed, the root is tapered and thermal expansion is allowed. The blade is free when stopped and tightened by centrifugal force. • Grub screw: a dovetail root secured against end movement by screws. • Welding: the blade is welded to the wheel."}]},{"n":43,"pg":325,"num":"5.4.1","title":"5.4.1 Blade Materials","sub":"Requirements and material families","src":"[Ganesan, Secs. 14.1, 14.4, pp. 501–513]","tx":[{"k":"p","t":"A turbine blade material must have high strength at the maximum temperature, low creep, resistance to oxidation and corro- sion, resistance to fatigue, and be easy to cast, forge, weld and machine."},{"k":"row","t":["Material Temperature capability","Notes"]},{"k":"p","t":"Steels Moderate Compressor and low-temperature stages. Titanium alloys up to about 550 °C (IMI 829)"},{"k":"p","t":"About half the density of steel; low thermal expansion; reacts with oxygen at high temperature. Nickel-base alloys"},{"k":"row","t":["Chromium (15–30 %) forms a protective oxide; also Al, Ti, Nb, Co. Vacuum melting. Ceramics Good at high temperature","up to about 925 °C (Nimonic 118)"]},{"k":"p","t":"Brittle and weak in thermal shock: not used for blades."}]},{"n":44,"pg":326,"num":"5.4.1","title":"5.4.1 Blade Manufacture and Creep","sub":"How blades are made, and why they fail","src":"[Ganesan, Secs. 14.2, 14.4, pp. 503–511; Pounder, Ch. 27, pp. 888–892]","tx":[{"k":"row","t":["Manufacture • Forging: compressor and LP turbine blades. • Casting (lost wax, vacuum): nickel and cobalt alloys; accurate shapes, hollow cooled blades. • Fabrication and powder metallurgy.","Creep • Above about 650–800 °C the metal no longer stays elastic and stretches slowly under load. • The blade lengthens, closes the tip clear- ance and can rub the casing. • At high temperature, life is creep-limited; at lower temperature it is corrosion- limited (Pounder)."]},{"k":"li","t":"Blade life is also limited by thermal fatigue and by the number of start–stop cycles."}]},{"n":45,"pg":327,"num":"5.4.2","title":"5.4.2 Blade Cooling: Need and Methods","sub":"Why and how blades are cooled","src":"[Ganesan, Secs. 14.4–14.7, pp. 511–516]","tx":[{"k":"li","t":"A higher turbine inlet temperature gives more power and higher efficiency, but the blade is the life-limiting part. The designer either finds a better material or cools the blade."},{"k":"li","t":"Cooling lets a blade run 200–300 °C below the gas temperature. With nickel alloys at an average blade temperature of 800 °C, the gas can reach about 1400 K."},{"k":"li","t":"Air is bled from the HP end of the compressor, about 600 °C cooler than the gas, at 1–3 % of the engine flow per blade row."},{"k":"p","t":"Classification By site: external (film, transpiration) and internal (convection, impingement). By medium: air (all present practice) and liquid (high heat transfer, but complex; corrosion and deposits)."}]},{"n":46,"pg":328,"num":"5.4.2","title":"5.4.2 External Cooling: Film and Transpiration","sub":"Cooling air over the blade surface","src":"[Ganesan, Sec. 14.5.1, pp. 513–514 (Figs. 14.7, 14.8)]","tx":[{"k":"fig","t":"Fig. 14.7 Film cooling. Fig. 14.8 Transpiration (effusion) cooling."},{"k":"li","t":"Film cooling: small holes (down to 0.15 mm, made by spark erosion) let cool air form a thin film on the surface; it insulates the metal and carries away radiated heat."},{"k":"li","t":"Transpiration: air sweats through a porous blade wall and blankets the blade; cooling is uniform."},{"k":"li","t":"Drawbacks of transpiration: low strength at high temperature, very small pores that clog, poor oxidation resistance."}]},{"n":47,"pg":329,"num":"5.4.2","title":"5.4.2 Internal Cooling: Convection and Impingement","sub":"Cooling air inside the blade","src":"[Ganesan, Sec. 14.5.2, p. 514 (Figs. 14.9, 14.10)]","tx":[{"k":"fig","t":"Fig. 14.9 Convection cooling: passages along the span. Fig. 14.10 Impingement cooling."},{"k":"li","t":"Convection: air flows from root to tip in passages (round or elliptical) and removes heat by conduction and convection; it leaves at the tip."},{"k":"li","t":"Impingement: air enters an inner shell and leaves through slots as jets that strike the inside of the leading and trailing edges; it then flows out through holes near the trailing edge."},{"k":"li","t":"Efficient cooling needs a large internal area and a high air velocity, so small passages."}]},{"n":48,"pg":330,"num":"5.4.2","title":"5.4.2 Practical Cooled Blades and the Z Factor","sub":"Triple-pass and double-pass blades","src":"[Ganesan, Secs. 14.7.3, 14.8, pp. 517–519 (Eq. 14.1, Figs. 14.14, 14.15)]","tx":[{"k":"fig","t":"Fig. 14.14 Tyne triple-pass blade. Fig. 14.15 Conway double-pass blade."},{"k":"p","t":"Coolant geometric parameter"},{"k":"p","t":"Z = S1.2"},{"k":"p","t":"c C1.2 × C2"},{"k":"p","t":"Ac — (14.1)"},{"k":"p","t":"Sc: internal surface per unit blade length, Ac: total passage area, C: chord. A high Z means a cooler blade: Z > 150 is needed, with little gain beyond 250. The Tyne (Z = 33) and Conway (Z = 31) blades have a low Z, so the air makes several passes. Tyne: 0.8 % air, 40 °C cooler, life 2000 →6500 h. Conway: 1.4 %, 120 °C cooler, 75 →13 000 h."}]},{"n":49,"pg":331,"num":"5.5.1","title":"5.5.1 Starting a Gas Turbine","sub":"Starting sequence","src":"[Ganesan, Sec. 10.10.3, p. 415; Pounder, Ch. 27, pp. 852, 866–867]","tx":[{"k":"li","t":"1. A starter accelerates the compressor to a speed whose airflow can sustain combustion."},{"k":"li","t":"2. During the acceleration the ignition is switched on and fuel is fed to the burners."},{"k":"li","t":"3. Once the flame is established it lights round from can to can through interconnecting tubes (no problem in an annular chamber)."},{"k":"li","t":"4. The turbine now produces more power than the compressor needs; the starter is disengaged through a clutch or cut-out."},{"k":"li","t":"5. The igniters are switched off; combustion is self-sustaining."},{"k":"p","t":"Marine gas turbines A free power turbine means only the gas generator is turned; with a two-spool engine only the HP rotor is turned, so even a large unit starts with a small starter or a battery. Idle is reached in about 30 s."}]},{"n":50,"pg":332,"num":"5.5.2","title":"5.5.2 Methods of Starting","sub":"Electric, air and hydraulic starters","src":"[Ganesan, Sec. 10.10.3, p. 415; Pounder, p. 870]","tx":[{"k":"p","t":"Method How it works Remark"},{"k":"p","t":"GT35 marine redesign went from pneumatic to electric. Compressed air (air starter motor)"},{"k":"p","t":"Electric An electric starter motor turns the main shaft through a reduction gear and clutch."},{"k":"row","t":["A small air turbine (or vane motor) driven by compressed air turns the shaft through gear and clutch; or air is fed directly to the turbine.","Needs an air receiver and compressor."]},{"k":"row","t":["Hydraulic A hydraulic motor supplied by a pump and accumulator turns the shaft through gear and clutch.","Flagged: not in the books."]},{"k":"p","t":"Cartridge A small turbine driven by a burning charge. Military aircraft only."},{"k":"flag","t":"Flagged: Ganesan names the electric motor, the compressed-air turbine and the cartridge. The air-starter-motor and hydraulic details are general practice and are not in Ganesan or Pounder."}]},{"n":51,"pg":333,"num":"5.5.3","title":"5.5.3 Ignition System","sub":"Surface-discharge igniter and torch igniter","src":"[Ganesan, Sec. 10.10.3, pp. 415–416 (Fig. 10.12)]","tx":[{"k":"fig","t":"Fig. 10.12 Surface-discharge igniter."},{"k":"li","t":"Ignition is needed only at start; an igniter plug sits near the primary zone in one or two cans."},{"k":"li","t":"Surface-discharge igniter: a capacitor discharge heats a semiconductor layer, ionising a path; the spark is about 3 J, one per second. It must project through the cooling-air layer to the edge of the fuel spray, but not be wetted."},{"k":"li","t":"Torch igniter: spark plug plus a small spray burner; suits vaporising chambers and heavy fuels; the burner can use distillate from a separate tank."},{"k":"li","t":"Ignition is harder at low pressure; the ignition loop lies inside the stability loop."}]},{"n":52,"pg":334,"num":"5.6.1","title":"5.6.1 Sources of Gas Turbine Noise","sub":"Where the noise comes from","src":"[Ganesan, Sec. 16.6, pp. 560–562]","tx":[{"k":"row","t":["External noise Caused by the exhaust jet mixing with the ambient air; it cannot be suppressed in- side the engine. Its level rises with about the eighth power of the jet velocity.","Internal noise Caused by the rotating machinery and the combustion; it can be suppressed or confined."]},{"k":"li","t":"Jet (exhaust) noise: turbulence where the fast exhaust meets the still air."},{"k":"li","t":"Fan or compressor noise: broad-band (turbulence), discrete tones (rotor–stator interaction), and multiple tones (supersonic tips)."},{"k":"li","t":"Core noise: compressor noise, combustion noise (turbulent burning) and turbine noise."},{"k":"flag","t":"Flagged: Ganesan treats noise for aircraft. For a ship, the strong sources are the air intake, the exhaust and the machinery casing."}]},{"n":53,"pg":335,"num":"5.6.2","title":"5.6.2 Noise Suppression Arrangement","sub":"Reducing the noise","src":"[Ganesan, Sec. 16.8, pp. 565–566; Pounder, Ch. 27, pp. 871, 887]","tx":[{"k":"li","t":"Lower the exhaust velocity: an exhaust mixer or a larger bypass reduces jet noise."},{"k":"li","t":"Acoustic liners in the inlet and exhaust ducts confine internal noise."},{"k":"li","t":"Blade design: lower tip speed, larger rotor–stator spacing, no inlet guide vanes, a different number of blades."},{"k":"li","t":"Marine package: an acoustic enclosure with insulation and damping around the engine, with intake and exhaust diffusers (MT30, WR-21)."},{"k":"li","t":"Silencers in the intake and exhaust ducts; flexible mounts for the package (5.8.5)."},{"k":"p","t":"Penalty Noise-reduction features usually add weight, length and cost, and can conflict with the best aerodynamic design."},{"k":"flag","t":"Flagged: the silencer and mounting layout is general marine practice; neither book shows it."}]},{"n":54,"pg":336,"num":"5.7.1","title":"5.7.1 Gas Turbines for Ship Propulsion: Overview","sub":"Where and why","src":"[Pounder, Ch. 27, pp. 851–853]","tx":[{"k":"row","t":["Main candidates • Warships (long established). • Cruise ships: compact; more cabins in the same hull. • Fast ferries and freight carriers. • LNG carriers and fast container ships.","Disadvantages • Higher fuel consumption, poor at part load. • Needs light distillate fuel (aero-derived types). • Large air and exhaust ducts."]},{"k":"li","t":"Merits: power-to-weight at least four times a medium-speed diesel (LM2500: 25 000 kW, 4.75 m long, 3.5 t); low noise and vibration; modular, easy replacement; lower NOx and SOx; automation; idle in about 30 s, instant restart."}]},{"n":55,"pg":337,"num":"5.7.1","title":"5.7.1 Where Marine Gas Turbines Are Used","sub":"Applications and examples","src":"[Pounder, Ch. 27, pp. 851–856, 876–879, 883]","tx":[{"k":"p","t":"Sector Why a gas turbine Examples"},{"k":"p","t":"Warships High power, small size, quick start."},{"k":"p","t":"Type 45: twin WR-21. Queen Elizabeth class: twin MT30. USS Freedom: twin MT30 and diesels. Fast ferries Power too high for"},{"k":"p","t":"Stena HSS: 68 000 kW, 40 knots (COGAG). Catamaran Francisco: two 25 MW LM2500, 58.2 knots (2013). Cruise ships"},{"k":"p","t":"diesels alone."},{"k":"row","t":["More cabins per hull; waste heat used.","Queen Mary 2: 117 200 kW, two LM2500+ and four diesels (CODEG). Royal Caribbean: first COGES, 2000."]},{"k":"p","t":"Small craft Small, light unit. Vericor TF40, 3000–3500 kW: yachts and hovercraft. Candidates Compact; can burn"},{"k":"p","t":"LNG carriers (designs approved in principle, 2014–18); fast container ships."},{"k":"p","t":"boil-off gas."},{"k":"li","t":"Commercial use is a niche: rising bunker prices and better diesels ended the 1970s container ships, a small gas carrier and the ferry Finnjet."}]},{"n":56,"pg":338,"num":"5.7.1","title":"5.7.1 Applications: Modules in Service","sub":"One module type, many ships","src":"[Pounder, Ch. 27, pp. 855, 878, 883 (Figs. 27.2, 27.17, 27.19)]","tx":[{"k":"fig","t":"Fig. 27.2 GE LM2500 module for a large"},{"k":"fig","t":"Fig. 27.17 Fully packaged Rolls-Royce"},{"k":"fig","t":"Fig. 27.19 Rolls-Royce MT30 gas turbine."},{"k":"row","t":["high-speed ferry.","Marine Spey module."]},{"k":"li","t":"LM2500 family: fast ferries, Queen Mary 2, COGES cruise ships, FREMM frigates. • Marine Spey: Royal Navy warships since 1985; also offered for water-jet ferries (p. 341). • MT30: Queen Elizabeth carriers and USS Freedom; up to 36 000 kW from a 25 t package. • Each turbine is a self-contained module: a faulty engine is exchanged, not repaired aboard (p. 346)."}]},{"n":57,"pg":339,"num":"5.7.1","title":"5.7.1 Plant Configurations","sub":"Combined propulsion plants","src":"[Pounder, Ch. 27, pp. 853–854 (Fig. 27.1)]","tx":[{"k":"fig","t":"Fig. 27.1 CODAG plant of a large monohull fast ferry."},{"k":"li","t":"CODOG: diesel or gas turbine; diesel for manoeuvring, turbine for high power. • CODAG: diesel and gas turbine to- gether. • COGAG: gas turbine and gas tur- bine (Stena HSS: LM2500 + LM1600, 68 000 kW). • COGOG: gas turbine or gas turbine. • CODLAG, CODEG: diesel and gas tur- bine electric (Queen Mary 2)."}]},{"n":58,"pg":340,"num":"5.7.1","title":"5.7.1 Combined Gas and Steam Plant (COGES)","sub":"Cruise ship power station","src":"[Pounder, Ch. 27, pp. 854–856 (Fig. 27.3)]","tx":[{"k":"fig","t":"Fig. 27.3 Layout of a COGES plant (GE Marine)."},{"k":"li","t":"Exhaust boilers in the gas turbine ex- haust make steam at about 30 bar for a steam turbine generator."},{"k":"li","t":"The steam turbine adds 15–18 % to the efficiency with no extra fuel, and gives a nearly constant fuel consumption over the load range."},{"k":"li","t":"Steam also serves the ship services, so no auxiliary boiler is fired."},{"k":"li","t":"Electric power drives the propulsion mo- tors."}]},{"n":59,"pg":341,"num":"5.7.2","title":"5.7.2 General Arrangement: Water-Jet Installation","sub":"Rolls-Royce Marine Spey machinery arrangement","src":"[Pounder, Ch. 27, pp. 877–878 (Fig. 27.16)]","tx":[{"k":"fig","t":"Fig. 27.16 Marine Spey machinery arrangement for a water-jet fast ferry."},{"k":"li","t":"The engine sits low in the hull between an air intake duct and an exhaust uptake to the funnel; the output shaft drives the water jet. • The shipbuilder’s interfaces are the intake and uptake flanges, the hull mountings and the output flange. • The module is just over 7.5 m long and weighs 17.5 t; the gas generator alone weighs 1.8 t. Compared with a diesel: about 80 % less weight and 60 % less space. • Power turbine: two stages, hydrodynamic bearings, clockwise or anti-clockwise rotation."}]},{"n":60,"pg":342,"num":"5.7.2","title":"5.7.2 Air Intake","sub":"Three-stage filtration","src":"[Pounder, Ch. 27, pp. 863–864]","tx":[{"k":"p","t":"Marine intake filter (three stages) 1. Vane separator: inertia removes large water droplets and spray (down to about 12 µm). 2. Coalescer / dust filter: small droplets and salt aerosol merge into larger drops; face velocity 6–8 m/s (2.5–3.5 m/s on land). 3. Second vane separator: stops liquid re-entrained from the coalescer; salt-laden water would damage the compressor."},{"k":"li","t":"The system should be compact (high velocity), keep a low pressure loss even when wet, and give good dust filtration and life."},{"k":"li","t":"The aerodynamics of the intake matter: it must feed the compressor evenly."},{"k":"flag","t":"Flagged: the intake duct layout (bellmouth, silencer, ducting to the engine) is general practice; only the filter is described in Pounder."}]},{"n":61,"pg":343,"num":"5.7.2","title":"5.7.2 Exhaust Uptake","sub":"Leading the exhaust to the funnel","src":"[Pounder, Ch. 27, pp. 867, 879]","tx":[{"k":"li","t":"The power turbine is surrounded by an exhaust volute that passes the gas to the atmosphere through a stack (uptake)."},{"k":"li","t":"The flow is large and hot: Marine Spey, 65.5 kg/s at 480 °C. The uptake needs a large area, expansion joints (thermal growth) and insulation."},{"k":"li","t":"The exhaust can feed a recuperator (ICR plant) or an exhaust boiler (COGES); it passes through a silencer (5.8.5)."},{"k":"li","t":"The outlet must keep the hot gas and exhaust smoke away from the air intake and from deck areas."},{"k":"li","t":"In a cruise-ship funnel installation, the long inlet and exhaust ducts are replaced by a short service trunk."},{"k":"flag","t":"Flagged: Pounder describes the volute and the funnel installation; the uptake design points are general practice."}]},{"n":62,"pg":344,"num":"5.7.3","title":"5.7.3 Ambient Conditions and Duct Losses","sub":"Effect on performance","src":"[Pounder, Ch. 27, p. 860; Ganesan, Sec. 6.4, pp. 143–145 (Eqs. 6.24–6.27)]","tx":[{"k":"row","t":["Ambient conditions • At sea level the air temperature and hu- midity vary widely. • Higher air temperature lowers effi- ciency and raises the fuel consumption. • Humidity matters less, but at high inlet temperature a higher humidity increases sfc.","Duct losses (intake and exhaust) • Losses before the turbine act like a lower compression pressure ratio; those after it, like a lower expansion ratio. • The exhaust side is critical: low pres- sure, large specific volume."]},{"k":"row","t":["˙m = ρAVf, ∆p ∝ρV 2 ∝ ˙m2","A2ρ, ∆p ∝1","d4 — (6.24–6.27)"]},{"k":"p","t":"The losses are small singly, but their sum is important; a larger duct area reduces them."}]},{"n":63,"pg":345,"num":"5.7.4","title":"5.7.4 Load Requirements","sub":"What the propulsion plant must deliver","src":"[Pounder, Ch. 27, pp. 853, 857, 867, 870]","tx":[{"k":"li","t":"Wide power range: high power for cruising, low power for manoeuvring and harbour work. The free power turbine runs at any speed from stop to full speed."},{"k":"li","t":"A propeller absorbs power roughly as P ∝n3; so a gas turbine spends much time at part load, where the simple cycle is least efficient (Fig. 27.5, p. 300)."},{"k":"li","t":"The remedy is a combined plant (CODOG, CODAG, COGAG, p. 339) or an ICR cycle with a flat sfc curve."},{"k":"li","t":"Water jets bring sudden large load changes, if air is drawn into the jet in a heavy sea."},{"k":"li","t":"Quick response: idle in about 30 s and rapid acceleration."},{"k":"flag","t":"Flagged: the propeller law is general theory; the other points are from Pounder."}]},{"n":64,"pg":346,"num":"5.7.5","title":"5.7.5 Service Requirements and Maintenance","sub":"Availability and maintenance","src":"[Pounder, Ch. 27, pp. 888–892]","tx":[{"k":"li","t":"The hot-section life (combustor, HP turbine blades and vanes) decides the maintenance interval; it is creep-limited at high temperature and corrosion-limited at lower temperature. A rating near the knee of the life curve is a good compromise."},{"k":"li","t":"Cyclic life: discs have a declared number of start–stop cycles, so short ferry runs raise the maintenance cost."},{"k":"li","t":"Routine on-board work: daily visual checks and fluid levels; an internal water wash after a fixed time to remove salt deposits from the compressor."},{"k":"li","t":"Repair by replacement: the GTCU (gas turbine change unit) is removed in 6–12 h; the power turbine stays for the life of the ship. Spare engines and power-by-the-hour contracts support availability."},{"k":"li","t":"The cost depends on the operating profile, starts and stops, ambient temperature and the maximum and minimum power."}]},{"n":65,"pg":347,"num":"5.7.5","title":"5.7.5 Considerations for Choosing Gas Turbine Propulsion","sub":"Selection factors","src":"[Pounder, Ch. 27, pp. 851–853, 860, 864]","tx":[{"k":"p","t":"Factor Consideration"},{"k":"p","t":"Space and weight High power density; the engine is often placed in the funnel; ducts take space."},{"k":"p","t":"Fuel Aero-derived engines burn distillate; an industrial type (GT35) can use heavy fuel after treatment."},{"k":"p","t":"Emissions Lower NOx and SOx than a diesel: three times the air needed for burning dilutes the exhaust. ICR recuperator bypass lowers NOx."},{"k":"p","t":"Efficiency Poor at part load: choose a combined plant or ICR cycle."},{"k":"p","t":"Operation Fast start, low manning, unmanned machinery space; the engine is matched to the ship, with fixed sizes and ratings."},{"k":"p","t":"Environment Salt in the air (filters), ambient temperature, ship motion (lubrication)."}]},{"n":66,"pg":348,"num":"5.7.6","title":"5.7.6 Gas Turbine Lubrication System Layout","sub":"Oil circuit and oil properties","src":"[Pounder, Ch. 27, pp. 861–862, 869, 871]","tx":[{"k":"p","t":"Layout of the oil circuit Oil tank →pressure pump →filter →oil cooler →bearings, gears and drives →scav- enge pumps →(de-aerator, breather) →tank"},{"k":"li","t":"The oil lubricates the bearings and, above all, cools them. It does not meet the combustion process."},{"k":"li","t":"The circulating quantity and the consumption are small (Marine Spey: about 0.1 L/h), so the oil works hard; peak oil temperature is over 200 °C in aero-derived engines."},{"k":"li","t":"Synthetic oils are used: they resist the temperature; mineral oils would oxidise, form gum and coke. Typical viscosity 5 cSt at 100 °C; low coking and good seal compatibility."},{"k":"li","t":"On ships the system is modified for vessel movement; the lube oil module can stand in the engine room."},{"k":"flag","t":"Flagged: neither book shows the oil circuit diagram; the chain above is the usual layout, compiled from the text."}]},{"n":67,"pg":349,"num":"5.8.1","title":"5.8.1 Reduction Gearing","sub":"Matching turbine and propeller speed","src":"[Pounder, Ch. 27, pp. 869, 871, 879]","tx":[{"k":"li","t":"A power turbine runs at 3300 to 5000 rev/min (GT35 3300; Marine Spey 5000); a propeller needs a much lower speed. A reduction gear is placed between them."},{"k":"p","t":"Gear ratio"},{"k":"row","t":["i = Npower turbine","(> 1)"]},{"k":"p","t":"Npropeller"},{"k":"li","t":"High-speed marine units use helical gears in single or double reduction; water-jet drives need a smaller ratio (pump speed is high)."},{"k":"li","t":"In CODAG and COGAG plants the gearbox combines the outputs of several engines, with clutches to disconnect an idle engine."},{"k":"li","t":"The GT35 power turbine is self-supported with its own journal and thrust bearing, so no thrust bearing is needed in the gearbox."},{"k":"flag","t":"Flagged: gear types and ratios are general marine practice; Pounder gives only the speeds and the thrust-bearing point."}]},{"n":68,"pg":350,"num":"5.8.2","title":"5.8.2 Starting and Reversing","sub":"Starting; reversing the ship","src":"[Pounder, Ch. 27, p. 867; Ganesan, Sec. 10.10.3]","tx":[{"k":"row","t":["Starting Starter motor (electric, air or hydraulic) → ignition →light-round →starter off (5.5). Only the gas generator is turned; the power turbine is free.","Reversing A gas turbine cannot reverse its rotation, so the drive is reversed."]},{"k":"li","t":"Reversing water jets: with a free power turbine give a flexible and effective propulsion system (Pounder)."},{"k":"li","t":"Controllable-pitch propeller: the blade pitch is reversed; the engine keeps its direction."},{"k":"li","t":"Reversing gear: clutches and an extra gear train reverse the output shaft."},{"k":"li","t":"Electric drive: the propulsion motor is reversed (COGES, CODLAG, CODEG)."},{"k":"flag","t":"Flagged: only the water-jet case is in Pounder; the other reversing methods are general practice."}]},{"n":69,"pg":351,"num":"5.8.3","title":"5.8.3 Accessories: Pumps and Drives","sub":"Engine-driven auxiliaries","src":"[Pounder, Ch. 27, pp. 870, 874, 871]","tx":[{"k":"li","t":"The HP turbine, through an accessory drive gearbox, drives the engine-mounted auxiliaries (LM2500, MFT-8)."},{"k":"li","t":"Fuel pump and fuel control (governor) to supply and meter the fuel."},{"k":"li","t":"Lube oil pump and scavenge pumps: the circulation of the oil (5.7.6)."},{"k":"li","t":"Hydraulic or air actuators: for variable stators, inlet guide vanes and variable-area nozzles (WR-21)."},{"k":"li","t":"Starter and its clutch (5.5); sensors, tachometers and the control and monitoring system."},{"k":"li","t":"In a package, the control panel, starter and lube module may stand away from the engine, in the engine room."},{"k":"flag","t":"Flagged: the list of accessories is compiled from the engine descriptions; neither book gives a full accessory layout."}]},{"n":70,"pg":352,"num":"5.8.4","title":"5.8.4 Fuel System","sub":"Supply, metering and injection","src":"[Ganesan, Secs. 10.10.2, 10.10.4, pp. 412–417; Pounder, Ch. 27, p. 869]","tx":[{"k":"p","t":"Fuel flow through an injector (Eq. 10.3)"},{"k":"p","t":"p"},{"k":"row","t":["˙mf = k A","2ρ p"]},{"k":"p","t":"A: nozzle area, p: injection pressure, ρ: fuel density, k: constant."},{"k":"li","t":"Chain: fuel tank →filter →HP fuel pump →throttle valve (fuel control) →manifold → injectors. The nozzles must be calibrated to share the fuel equally."},{"k":"li","t":"Flow varies as √p, so the valve sets the pressure and the pressure sets the flow."},{"k":"li","t":"Spill-flow system (GT35): a regulating valve in the return pipe governs the injection; fuel can circulate through the injectors to warm them before light-up (high-viscosity fuels)."},{"k":"li","t":"Heavy fuel needs heating, washing and additives (vanadium, sodium) before it reaches the engine."}]},{"n":71,"pg":353,"num":"5.8.5","title":"5.8.5 Intake Filters, Inlet and Exhaust Silencers","sub":"Cleaning the air; quietening the ducts","src":"[Pounder, Ch. 27, pp. 863–864, 871, 887]","tx":[{"k":"row","t":["Intake filter Vane separator →coalescer →vane separator (5.7.2). Removes spray, salt and dust; the pressure loss must stay low when wet.","Silencers Fitted in the inlet and exhaust ducts; they take the sound out of the airflow and gas flow."]},{"k":"li","t":"Typical silencer: parallel splitter panels filled with sound-absorbing material; the sound is absorbed as the flow passes between them."},{"k":"li","t":"The package has inlet and exhaust diffusers and an acoustic enclosure (MT30)."},{"k":"li","t":"A silencer adds pressure loss, so it must be sized with the duct losses in mind (p. 344)."},{"k":"flag","t":"Flagged: silencer construction is general practice; neither book describes the layout."}]},{"n":72,"pg":354,"num":"","title":"Unit V: Summary of Key Points and Formulas","sub":"Gas turbines","src":"[Ganesan, Chs. 4–5, 10, 14; Pounder, Ch. 27]","tx":[{"k":"p","t":"Topic Key points"},{"k":"p","t":"√"},{"k":"row","t":["Simple cycle η = 1 −1/p(γ−1)/γ","R ; maximum work at p(γ−1)/γ"]},{"k":"row","t":["t (T2 = T4). Heat exchange","R ="]},{"k":"row","t":["η = 1 −p(γ−1)/γ","R /t; best at low pR, high t; work unchanged."]},{"k":"p","t":"Arrangements Single shaft, twin shaft (free power turbine), twin spool; intercooling, reheating, recuperation. Combustion Primary 15–20 %, secondary about 30 %, tertiary (dilution) the rest. Turbine, blades"},{"k":"p","t":"NGV + rotor; fir-tree root; Ni alloys; creep above 650–800 °C; 1–3 % cooling air; Z > 150 (low Z: multi-pass). Start, noise Starter, ignition, light-round; liners, silencers, enclosure. Marine plant Three-stage intake filter; CODAG, COGES; reduction gear; synthetic oil; module replacement."}]}];
